package br.com.loja.order;import br.com.loja.order.dto.*;import br.com.loja.product.*;import org.springframework.http.*;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class OrderService{private final OrderRepository orders;private final ProductRepository products;private final SimpMessagingTemplate msg;public OrderService(OrderRepository o,ProductRepository p,SimpMessagingTemplate m){orders=o;products=p;msg=m;}public List<CustomerOrder> list(String email,boolean admin){return admin?orders.findAllByOrderByCreatedAtDesc():orders.findByUserEmailOrderByCreatedAtDesc(email);}@Transactional public CustomerOrder checkout(CheckoutRequest q,String email){CustomerOrder o=new CustomerOrder(email,q.customerName(),q.shippingAddress());for(var l:q.items()){Product p=products.findById(l.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Produto não encontrado"));if(!p.isActive())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Produto inativo: "+p.getName());if(p.getStock()<l.quantity())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Estoque insuficiente para "+p.getName());p.setStock(p.getStock()-l.quantity());products.save(p);o.add(new OrderItem(p.getId(),p.getName(),l.quantity(),p.getPrice()));}CustomerOrder saved=orders.save(o);msg.convertAndSend("/topic/store",Map.of("action","ORDER_CREATED","orderId",saved.getId()));return saved;}@Transactional public CustomerOrder status(Long id,OrderStatus status){CustomerOrder o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido não encontrado"));if(o.getStatus()==OrderStatus.CANCELED&&status!=OrderStatus.CANCELED)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Pedido cancelado não pode ser reaberto");if(status==OrderStatus.CANCELED&&o.getStatus()!=OrderStatus.CANCELED){for(OrderItem item:o.getItems()){products.findById(item.getProductId()).ifPresent(p->{p.setStock(p.getStock()+item.getQuantity());products.save(p);});}}o.setStatus(status);o=orders.save(o);msg.convertAndSend("/topic/store",Map.of("action","ORDER_STATUS","orderId",o.getId()));return o;}}
